public ConnectionResponse register(RegisterConnectionRequest req) {
    boolean crossesMidnight = Boolean.TRUE.equals(req.crossesMidnight());
    int guarantee = req.guaranteeMinutes();
    if (guarantee < MIN || guarantee > MAX) throw unprocessable("GUARANTEE_RANGE_INVALID", ..., details actual/requiredMin/requiredMax)
    String hash = hashConnect(req, crossesMidnight);
    replay...
    try {
        return tx.execute(status -> {
            planRepo.acquirePublishLock();
            DayPlan pred = planRepo.findByKeyForUpdate(req.predecessorKey()).orElseThrow(notFound);
            DayPlan succ = planRepo.findByKeyForUpdate(req.successorKey()).orElseThrow(notFound);
            if (pred.id() == succ.id()) throw unprocessable("CONNECTION_INVALID", "前后车必须为不同计划");
            requirePublished(pred, "前车"); requirePublished(succ, "后车");
            // 运营日规则
            if (succ.opDate().equals(pred.opDate())) { } 
            else if (crossesMidnight && succ.opDate().equals(pred.opDate().plusDays(1))) { }
            else throw unprocessable("OP_DATE_MISMATCH", ...);
            List<Occupancy> predOccs = planRepo.findOccupancies(pred.id());
            List<Occupancy> succOccs = planRepo.findOccupancies(succ.id());
            Occupancy predLast = max by endUtc (tie seq);
            Occupancy succFirst = min by startUtc (tie seq);
            Section predSection = sectionRepo.find(predLast.sectionId()).orElseThrow(422 SECTION_UNKNOWN);
            Section succSection = sectionRepo.find(succFirst.sectionId()).orElseThrow(422 SECTION_UNKNOWN);
            if (!predSection.toStation().equals(succSection.fromStation())) throw 422 STATION_NOT_CONTINUOUS details{arrivalStation, departureStation}
            if (connRepo.findActive(pred.id(), succ.id()).isPresent()) throw conflict CONNECTION_EXISTS (409)
            long actual = Duration.between(predLast.endUtc(), succFirst.startUtc()).toMinutes();
            if (actual < guarantee) throw 422 GUARANTEE_INSUFFICIENT details{requiredMinutes, actualMinutes, shortfallMinutes}
            long now = clock.millis();
            long connId = connRepo.insert(pred.id(), succ.id(), guarantee, crossesMidnight, now);
            connRepo.insertEvent(new ConnectionEvent(0, connId, REGISTERED, pred.id(), succ.id(), pred.version(),
                predLast.endUtc(), succFirst.startUtc(), guarantee, (int)actual, (int)(guarantee-actual), null, null, now));
            ConnectionResponse response = toResponse(connRepo.findById(connId).orElseThrow());
            idemRepo.insert(OP_CONNECT, req.requestKey(), hash, toJson(response), now);
            return response;
        });
    } catch (DuplicateKeyException e) {
        return replayIfPresent(...).orElseThrow(conflict CONNECTION_EXISTS);
    }
}
```

