```java
private Instant[] window(Connection conn, Instant predEnd, DayPlan succ) {
    List<Occupancy> occs = planRepo.findOccupancies(succ.id());
    Instant first = min start; Instant last = max end;
    long spanMs = last - first;
    Instant windowStart = predEnd.plus(conn.guaranteeMinutes(), MINUTES);
    Instant dayEnd = succ.opDate().plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
    if (conn.crossesMidnight()) dayEnd = dayEnd.plus(1, DAYS);
    Instant windowEnd = dayEnd.minusMillis(spanMs);
    return {windowStart, windowEnd};
}
```

