private long computeShift(DayPlan p, List<Occupancy> occs, Set<Long> batchIds,
                          Map<Long, List<Occupancy>> shifted, long now) {
    Instant firstStart = min start;
    long minShiftMs = 0;
    boolean crossesMidnight = false;
    for (Connection c : connRepo.findActiveBySuccessor(p.id())) {
        Instant predEnd = effectiveLastEnd(c.predecessorPlanId(), shifted);
        long required = predEnd.toEpochMilli() + c.guaranteeMinutes()*60000L - firstStart.toEpochMilli();
        minShiftMs = Math.max(minShiftMs, required);
        crossesMidnight |= c.crossesMidnight();
    }
    for (Connection c : connRepo.findActiveByPredecessor(p.id())) crossesMidnight |= c.crossesMidnight();
    Instant dayEnd = p.opDate().plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
    if (crossesMidnight) dayEnd = dayEnd.plus(1, DAYS);
    // 其他已发布计划（排除本批次）的生效时隙
    List<String> sectionIds = occs.stream().map(sectionId).distinct sorted;
    List<PublishedSlot> slots = planRepo.findPublishedSlots(p.opDate(), sectionIds, batchIds);
    // 注意：跨零点时占用可能落到下一运营日，已发布时隙查询按 opDate 过滤会漏掉次日的占用。
```

