                planRepo.updateConnectionRisk(newSucc.id(), ConnectionRisk.CONNECTION_AT_RISK.name(), now);
                connRepo.insertEvent(riskEvent(conn, pred, newSucc, oldFirst, newFirst, actual, now));
            }
        } else {
            clearRiskIfSatisfied(newSucc.id(), now);
        }
