        for (int i = 0; i < MAX_SHIFT_SEARCH_ITERATIONS; i++) {
            List<Occupancy> candidate = shiftOccupancies(occs, shift);
            Instant lastEnd = candidate.stream().map(Occupancy::endUtc)
                    .max(Comparator.naturalOrder()).orElseThrow();
