        assertThat(riskEvent.get("actualMinutes").asInt()).isEqualTo(-50);
        assertThat(riskEvent.get("shortfallMinutes").asInt()).isEqualTo(70);
        assertThat(riskEvent.get("windowStartUtc").asText()).isEqualTo(iso(10, 40));
